BEGIN
CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0680000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 68, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "68", "printedPageNumber": 68, "pdfPageNumber": 451, "sequenceIndex": 58, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0680100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—II", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0680200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—III", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0680300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—IV", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0680000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "anho) says, \"When the Prophet (Sallallaho alaihe wasallam) deputed me to Yemen, I requested him to give me some parting advice. He replied, ''Be sincere in all your services, as sincerity will magnify the value of an action, however insignificant it may be.''\"\n\nHadhrat Thaubaan (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Blessed be the sincere ones, for they are the lamps of guidance. They cause the worst evils to be driven off through their sincerity.\" It is said in another hadith, \"It is through the presence of the weak and due to their salaat and their sincerity that Allah''s help comes to all the people.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680200-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680300-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680400-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Woe unto worshippers who are heedless of their salaat, who want but to be seen at salaat.\" (CVII: 4–6)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680500-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "\"To be heedless\" has been given the following different interpretations:\n\n1. To be so careless as to miss the correct time of salaat.\n2. To be inattentive in salaat.\n3. To forget the number of rakaats.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680600-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680700-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَىٰ يُرَاءُونَ النَّاسَ وَلَا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680800-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"When they (the hypocrites) stand up for salaat, they perform it without earnestness and want but to be seen by men and are mindful of Allah but little.\" (IV: 142)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680900-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0681000-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلَاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0681100-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Now there hath succeeded them (Prophets) a later generation who have ruined salaat and have followed lusts. So they will meet Ghayy.\" (XIX: 59)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0690000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 69, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "69", "printedPageNumber": 69, "pdfPageNumber": 452, "sequenceIndex": 59, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0690100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—V", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0690200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—VI", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0690000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "In the dictionary ''Ghayy,'' is explained as deception, which points towards the awful doom and ruin in the hereafter. According to many commentators, Ghayy is a pit in Hell full of blood and pus. The persons who had ruined their salaat shall be thrown into this pit.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690200-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690300-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَمَا مَنَعَهُمْ أَنْ تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ إِلَّا أَنَّهُمْ كَفَرُوا بِاللَّهِ وَبِرَسُولِهِ وَلَا يَأْتُونَ الصَّلَاةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنْفِقُونَ إِلَّا وَهُمْ كَارِهُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690400-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And naught preventeth that their (the hypocrites) contributions should be accepted from them, save that they have disbelieved in Allah and in His Apostle, and they come not to worship, save as idlers, and pay not (their contribution) save reluctantly.\" (IV: 54)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690500-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Note: The quotations I to V above relate to those who ruin salaat. On the other hand, the following speak of those whom Allah praises for their good salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690600-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690700-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ ۝ وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ ۝ وَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ ۝ وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَىٰ أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَىٰ وَرَاءَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْعَادُونَ ۝ وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ ۝ وَالَّذِينَ هُمْ عَلَىٰ صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُولَٰئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690800-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Successful indeed are the believers who are humble in their salaat. And who shun vain conversation. And who are payers of the Zakaat. And who abstain from sex, save from their wives or the slaves that their right hand possess, for then they are not blameworthy but who craveth beyond that, such are transgressors—And who faithfully observe their pledges and their covenants. And who pay heed to their salaat. These are the heirs who will inherit Firdaus (Paradise). There they will abide.\" (XXIII: 1 to 11)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690900-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) says, \"Firdaus is the apex and the best portion of Paradise, where", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0700000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 70, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "70", "printedPageNumber": 70, "pdfPageNumber": 453, "sequenceIndex": 60, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0700100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—VII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0700200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—VIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0700000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "from all its rivers originate. Allah''s throne will be placed there. When you pray for Paradise, always pray for Firdaus.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700200-0000-4000-8000-000000000001", "structuralNodeId": "b0700100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700300-0000-4000-8000-000000000001", "structuralNodeId": "b0700100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ ۝ الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلَاقُو رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَاجِعُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700400-0000-4000-8000-000000000001", "structuralNodeId": "b0700100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And truly it (salaat) is hard save for the humble-minded; who know that they have to meet their Lord, and that unto Him they are returning.\" (II: 45–46)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700500-0000-4000-8000-000000000001", "structuralNodeId": "b0700200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—VIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700600-0000-4000-8000-000000000001", "structuralNodeId": "b0700200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ يُسَبِّحُ لَهُ فِيهَا بِالْغُدُوِّ وَالْآصَالِ ۝ رِجَالٌ لَا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَنْ ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ الْقُلُوبُ وَالْأَبْصَارُ ۝ لِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا عَمِلُوا وَيَزِيدَهُمْ مِنْ فَضْلِهِ وَاللَّهُ يَرْزُقُ مَنْ يَشَاءُ بِغَيْرِ حِسَابٍ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700700-0000-4000-8000-000000000001", "structuralNodeId": "b0700200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"In houses which Allah hath allowed to be exalted, and His name shall be remembered therein, do offer praise to Him at morning and evening, men whom neither merchandise nor sale beguileth from remembrance of Allah and establishment of salaat and paying Zakaat, who fear that Day when the hearts and the eyeballs will be over-turned so that Allah may reward them for the best of what they did and increase reward for them out of His bounty. Allah giveth blessings without measure to whom He will.\" (XXIV: 36 to 38)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700800-0000-4000-8000-000000000001", "structuralNodeId": "b0700200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Abbas (Radhiyallaho anho) says, \"Establishment of salaat means performance of ruku and sajdah, properly and constant concentration in salaat with complete humility and submission.\" Hadhrat Qataadah (Radhiyallaho anho) says: \"Wherever the words ''Establishment of salaat'' occur in Qur''an, they mean to guard its hours, to perform wudhu in the right manner and to observe ruku and sajdah properly.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;